 public static class SaveOwner {
  public const int CurrentVersion=29;
  public static void Migrate(GameSave s){if(s==null)return;if(s.SaveVersion<2){if(s.Battles==null)s.Battles=new List<BattleReport>();s.SaveVersion=2;}if(s.SaveVersion<3){if(s.Projects==null)s.Projects=new List<ConstructionProject>();s.SaveVersion=3;}if(s.SaveVersion<4){if(s.Diplomacy==null)s.Diplomacy=new List<DiplomacyRelation>();s.SaveVersion=4;}if(s.SaveVersion<5){if(s.MerchantInvestments==null)s.MerchantInvestments=new List<MerchantInvestment>();if(s.WarAdministrations==null)s.WarAdministrations=new List<WarAdministration>();if(s.Sieges==null)s.Sieges=new List<SiegeState>();s.SaveVersion=5;}if(s.SaveVersion<6){if(s.Herds==null)s.Herds=new List<AnimalHerd>();s.SaveVersion=6;}if(s.SaveVersion<7){s.IdSequence=Math.Max(1000,s.IdSequence);s.TimeScale=s.TimeScale<=0?1f:s.TimeScale;s.SaveVersion=7;}if(s.SaveVersion<8){if(s.Equipment!=null)foreach(EquipmentInstance e in s.Equipment){if(e==null)continue;if(string.IsNullOrEmpty(e.DisplayName))e.DisplayName=e.TemplateId;if(e.History==null)e.History=new List<string>();}s.SaveVersion=8;}if(s.SaveVersion<9){if(s.SupplyRoutes==null)s.SupplyRoutes=new List<SupplyRoute>();if(s.SupplyConvoys==null)s.SupplyConvoys=new List<SupplyConvoy>();if(s.Map!=null&&s.Map.Tiles!=null)foreach(WorldTile t in s.Map.Tiles)if(t!=null&&t.Road){if(t.RoadLevel<=0)t.RoadLevel=1;if(t.RoadCapacity<=0)t.RoadCapacity=2;}s.SaveVersion=9;}if(s.SaveVersion<10){if(s.Kingdoms!=null)foreach(Kingdom k in s.Kingdoms)if(k!=null&&k.SuspendedPolicyIds==null)k.SuspendedPolicyIds=new List<string>();s.SaveVersion=10;}if(s.SaveVersion<11){if(s.Cities!=null)foreach(City c in s.Cities)if(c!=null){if(c.FortificationRadius<0)c.FortificationRadius=0;if(c.FortificationPlanVersion<0)c.FortificationPlanVersion=0;}s.SaveVersion=11;}if(s.SaveVersion<12){if(s.Armies!=null)foreach(Army a in s.Armies)if(a!=null){a.MusterProgress=Mathx.Clamp(a.MusterProgress,0f,1f);if(a.Order!=ArmyOrder.Muster&&a.MusterProgress<1f)a.MusterProgress=0f;}s.SaveVersion=12;}if(s.SaveVersion<13){if(s.People!=null)foreach(Person p in s.People)if(p!=null){if(p.Injury!=InjuryState.Captured){p.CapturedByKingdomId="";p.CapturedDay=-1;p.RansomValue=0;}else if(p.CapturedDay<0)p.CapturedDay=0;}if(s.Sieges!=null)foreach(SiegeState state in s.Sieges)if(state!=null&&state.LastAssaultBattleDay<0)state.LastAssaultBattleDay=-1;s.SaveVersion=13;}if(s.SaveVersion<14){if(s.Armies!=null)foreach(Army a in s.Armies)if(a!=null)a.LastBattleDay=-1;s.SaveVersion=14;}if(s.SaveVersion<15){if(s.Kingdoms!=null)foreach(Kingdom k in s.Kingdoms)if(k!=null){if(k.Status==KingdomStatus.Vassal&&string.IsNullOrEmpty(k.OverlordKingdomId))k.Status=KingdomStatus.Active;if(k.Status!=KingdomStatus.Vassal)k.OverlordKingdomId="";if(k.Status==KingdomStatus.Active)k.DefeatDay=-1;}if(s.Diplomacy!=null)foreach(DiplomacyRelation r in s.Diplomacy)if(r!=null&&r.State!=DiplomacyState.Vassal){r.SuzerainId="";r.VassalId="";}s.SaveVersion=15;}if(s.SaveVersion<16){if(s.Battles!=null)foreach(BattleReport b in s.Battles)if(b!=null){b.LightAttacks=Math.Max(0,b.LightAttacks);b.HeavyAttacks=Math.Max(0,b.HeavyAttacks);b.ThrustAttacks=Math.Max(0,b.ThrustAttacks);b.RangedAttacks=Math.Max(0,b.RangedAttacks);b.CavalryCharges=Math.Max(0,b.CavalryCharges);b.Dodges=Math.Max(0,b.Dodges);b.Parries=Math.Max(0,b.Parries);b.ShieldBlocks=Math.Max(0,b.ShieldBlocks);}s.SaveVersion=16;}if(s.SaveVersion<17){if(s.Projects!=null)foreach(ConstructionProject p in s.Projects)if(p!=null&&p.WorkerActions==null)p.WorkerActions=new List<ConstructionWorkerAction>();if(s.Armies!=null)foreach(Army a in s.Armies)if(a!=null&&a.Squads!=null)foreach(Squad q in a.Squads)if(q!=null){q.LocalMoraleState=MoraleSystem.State(q.Morale);if(q.RoutWave<0)q.RoutWave=0;}s.SaveVersion=17;}if(s.SaveVersion<18){if(s.Map!=null&&s.Map.Tiles!=null)foreach(WorldTile t in s.Map.Tiles)if(t!=null){t.SurfaceMud=Mathx.Clamp(t.SurfaceMud,0f,1f);t.SnowDepth=Mathx.Clamp(t.SnowDepth,0f,1f);if(t.Road){if(t.RoadCondition<=0f)t.RoadCondition=1f;t.RoadCondition=Mathx.Clamp(t.RoadCondition,.25f,1f);}else t.RoadCondition=0f;if(t.WeatherExposureDays<0)t.WeatherExposureDays=0;}s.SaveVersion=18;}if(s.SaveVersion<19){if(s.Cities!=null)foreach(City c in s.Cities)if(c!=null&&c.Zones==null)c.Zones=new List<CityZone>();s.SaveVersion=19;}if(s.SaveVersion<20){if(s.ActiveBattles==null)s.ActiveBattles=new List<BattleSession>();s.SaveVersion=20;}if(s.SaveVersion<21){int bi=0;if(s.ActiveBattles!=null)foreach(BattleSession session in s.ActiveBattles){if(session!=null&&session.RandomState==0)session.RandomState=(uint)(s.Seed^session.StartDay^session.ElapsedSeconds^(++bi*7919));}s.SaveVersion=21;}if(s.SaveVersion<22){if(s.ComputerDifficulty<0||s.ComputerDifficulty>3)s.ComputerDifficulty=2;s.SaveVersion=22;}if(s.SaveVersion<23){if(s.Events==null)s.Events=new List<WorldEvent>();s.SaveVersion=23;}if(s.SaveVersion<24){if(s.Armies!=null)foreach(Army a in s.Armies)if(a!=null){if(a.CampStartDay<0)a.CampStartDay=-1;if(a.Order!=ArmyOrder.Camp&&a.ResumeOrder==ArmyOrder.Camp)a.ResumeOrder=ArmyOrder.March;}s.SaveVersion=24;}if(s.SaveVersion<25){if(s.Armies!=null)foreach(Army a in s.Armies)if(a!=null&&a.Deserters<0)a.Deserters=0;s.SaveVersion=25;}if(s.SaveVersion<26){if(s.WarAdministrations==null)s.WarAdministrations=new List<WarAdministration>();s.SaveVersion=26;}if(s.SaveVersion<27){if(s.People!=null)foreach(Person p in s.People)if(p!=null){if(p.CivicMerit<0)p.CivicMerit=0;if(p.LastMeritReason==null)p.LastMeritReason="";}if(s.Cities!=null)foreach(City c in s.Cities)if(c!=null){if(c.LastCapturedDay<0)c.LastCapturedDay=-1;if(c.PreviousKingdomId==null)c.PreviousKingdomId="";if(c.Occupation==OccupationPolicy.Pending&&c.LastCapturedDay<0)c.Occupation=OccupationPolicy.None;}s.SaveVersion=27;}if(s.SaveVersion<28){if(s.Map!=null){s.Map.LegacyGenerator=true;s.Map.SeaLevel=.24f;int dry=0;if(s.Map.Tiles!=null)foreach(WorldTile tile in s.Map.Tiles)if(tile!=null&&tile.Terrain!=TerrainKind.DeepWater&&tile.Terrain!=TerrainKind.Coast&&tile.Terrain!=TerrainKind.Lake)dry++;s.Map.GenerationOptions=new WorldGenerationOptions{LandPercent=s.Map.Tiles==null||s.Map.Tiles.Length==0?55:Mathx.Clamp((int)Math.Round(100f*dry/s.Map.Tiles.Length),15,85)};}s.SaveVersion=28;}if(s.SaveVersion<29){s.SimulationTick=(long)Math.Floor((s.Day*30f+s.TimeIntoDaySeconds)/SimulationClock.FixedStep);s.TickPendingSeconds=0f;if(s.ProcessedCommandIds==null)s.ProcessedCommandIds=new List<string>();s.SaveVersion=29;}Normalize(s);}
  static void Normalize(GameSave s){if(s.ProcessedCommandIds==null)s.ProcessedCommandIds=new List<string>();if(s.Events==null)s.Events=new List<WorldEvent>();if(s.ActiveBattles==null)s.ActiveBattles=new List<BattleSession>();if(s.People==null)s.People=new List<Person>();if(s.Families==null)s.Families=new List<Family>();if(s.Cities==null)s.Cities=new List<City>();if(s.Kingdoms==null)s.Kingdoms=new List<Kingdom>();if(s.Armies==null)s.Armies=new List<Army>();if(s.Buildings==null)s.Buildings=new List<Building>();if(s.Equipment==null)s.Equipment=new List<EquipmentInstance>();if(s.Projects==null)s.Projects=new List<ConstructionProject>();if(s.Proposals==null)s.Proposals=new List<Proposal>();if(s.Battles==null)s.Battles=new List<BattleReport>();if(s.Diplomacy==null)s.Diplomacy=new List<DiplomacyRelation>();if(s.MerchantInvestments==null)s.MerchantInvestments=new List<MerchantInvestment>();if(s.WarAdministrations==null)s.WarAdministrations=new List<WarAdministration>();if(s.Sieges==null)s.Sieges=new List<SiegeState>();if(s.Herds==null)s.Herds=new List<AnimalHerd>();if(s.SupplyRoutes==null)s.SupplyRoutes=new List<SupplyRoute>();if(s.SupplyConvoys==null)s.SupplyConvoys=new List<SupplyConvoy>();foreach(SupplyRoute r in s.SupplyRoutes)if(r!=null&&r.Path==null)r.Path=new List<GridPoint>();foreach(Kingdom k in s.Kingdoms)if(k!=null){if(k.ActivePolicyIds==null)k.ActivePolicyIds=new List<string>();if(k.SuspendedPolicyIds==null)k.SuspendedPolicyIds=new List<string>();}foreach(City c in s.Cities)if(c!=null){if(c.Zones==null)c.Zones=new List<CityZone>();if(c.PreviousKingdomId==null)c.PreviousKingdomId="";if(c.LastCapturedDay<0)c.LastCapturedDay=-1;}foreach(Person p in s.People){if(p==null)continue;if(p.TraitIds==null)p.TraitIds=new List<string>();if(p.CommanderSkillIds==null)p.CommanderSkillIds=new List<string>();if(p.EquipmentIds==null)p.EquipmentIds=new List<string>();if(p.Stats==null)p.Stats=new Stats();if(p.WalkRoute==null)p.WalkRoute=new List<GridPoint>();if(p.CivicMerit<0)p.CivicMerit=0;if(p.LastMeritReason==null)p.LastMeritReason="";}foreach(Army a in s.Armies){if(a==null)continue;if(a.Squads==null)a.Squads=new List<Squad>();if(a.SubGeneralIds==null)a.SubGeneralIds=new List<string>();if(a.StrategicRoute==null)a.StrategicRoute=new List<GridPoint>();if(a.FormerGeneralIds==null)a.FormerGeneralIds=new List<string>();if(a.FamousBattles==null)a.FamousBattles=new List<string>();if(a.Finance==null)a.Finance=new MilitaryAccount();a.MarchProgress=Mathx.Clamp(a.MarchProgress,0f,16f);foreach(Squad q in a.Squads)if(q!=null&&q.SoldierIds==null)q.SoldierIds=new List<string>();}foreach(Proposal p in s.Proposals)if(p!=null&&p.Effects==null)p.Effects=new List<NumericEffect>();foreach(WarAdministration w in s.WarAdministrations)if(w!=null&&string.IsNullOrEmpty(w.LastAction))w.LastAction="尚未下达战务";foreach(ConstructionProject p in s.Projects)if(p!=null){if(p.WorkerIds==null)p.WorkerIds=new List<string>();if(p.WorkerActions==null)p.WorkerActions=new List<ConstructionWorkerAction>();}foreach(BattleSession session in s.ActiveBattles)if(session!=null){if(session.Report==null)session.Report=new BattleReport{Id=Ids.Next("BATTLE"),AttackerArmyId=session.AttackerArmyId,DefenderArmyId=session.DefenderArmyId,StartDay=session.StartDay,LocationName=session.LocationName,ResultText="交战中"};if(session.Report.Highlights==null)session.Report.Highlights=new List<string>();session.ElapsedSeconds=Math.Max(0,session.ElapsedSeconds);session.MaxSeconds=Math.Max(0,session.MaxSeconds);if(session.RandomState==0)session.RandomState=(uint)(s.Seed^session.StartDay^session.ElapsedSeconds^0x5f3759df);}foreach(BattleReport b in s.Battles)if(b!=null&&b.Highlights==null)b.Highlights=new List<string>();}
